/**
 * doc-parser.js — Document parsing registry and utilities for AI file upload.
 *
 * Architecture
 * ────────────
 * Each supported file format registers an entry in PARSER_REGISTRY:
 *   - extensions : string[]    — file extensions this parser handles (lowercase, with dot)
 *   - description: string      — human-readable format name (used in error messages)
 *   - parse(buf)  : fn→string  — synchronous or async function; returns extracted text
 *
 * To add a new document format:
 *   1. npm install <parsing-library>
 *   2. Add an entry to PARSER_REGISTRY
 *   3. Done — the upload handler auto-discovers supported formats from the registry.
 *
 * Supported formats
 * ─────────────────
 * Binary  : PDF (.pdf), Word (.docx), Excel (.xlsx / .xls)
 * Textual : CSV, TXT, MD, JSON, XML, YAML, YML
 * Fallback: any non-binary UTF-8 file (detected via printable-char ratio)
 */

var path = require("path");

// ─── Parsing libraries (optional dependencies) ───────────────────────────────
var pdfParse;
try { pdfParse = require("pdf-parse"); } catch (e) { pdfParse = null; }

var mammoth;
try { mammoth = require("mammoth"); } catch (e) { mammoth = null; }

var XLSX;
try { XLSX = require("xlsx"); } catch (e) { XLSX = null; }


// ─── Constants ───────────────────────────────────────────────────────────────

/** Maximum upload size in bytes (200 MB). Must match multer limit in index.js. */
var MAX_FILE_SIZE = 200 * 1024 * 1024;

/** Text-based extensions — safe to decode as UTF-8 directly. */
var TEXT_EXTENSIONS = [".csv", ".txt", ".md", ".json", ".xml", ".yaml", ".yml"];

/** Binary extensions — require a dedicated parsing library. */
var BINARY_EXTENSIONS = [".pdf", ".docx", ".xlsx", ".xls"];

/** All explicitly supported extensions (union of text + binary). */
var SUPPORTED_EXTENSIONS = TEXT_EXTENSIONS.concat(BINARY_EXTENSIONS);


// ─── Parser Registry ─────────────────────────────────────────────────────────
//
// Each key is a human-readable format name.  The value describes which
// extensions the parser handles and how to extract plain-text from a Buffer.
//
// When adding a new parser, simply push a new entry — the rest of the
// pipeline (extension lookup, error messages, size checks) adapts automatically.

var PARSER_REGISTRY = {
    pdf: {
        extensions: [".pdf"],
        description: "PDF",
        parse: function (buf) {
            if (!pdfParse) {
                return Promise.reject(new Error("pdf-parse module not installed"));
            }
            return pdfParse(buf).then(function (data) { return data.text; });
        }
    },
    docx: {
        extensions: [".docx"],
        description: "Word Document",
        parse: function (buf) {
            if (!mammoth) {
                return Promise.reject(new Error("mammoth module not installed"));
            }
            return mammoth.extractRawText({ buffer: buf }).then(function (result) {
                return result.value;
            });
        }
    },
    xlsx: {
        extensions: [".xlsx", ".xls"],
        description: "Excel Spreadsheet",
        parse: function (buf) {
            if (!XLSX) {
                return Promise.reject(new Error("xlsx module not installed"));
            }
            try {
                var wb = XLSX.read(buf, { type: "buffer" });
                var sheets = wb.SheetNames.map(function (name) {
                    var csv = XLSX.utils.sheet_to_csv(wb.Sheets[name]);
                    if (!csv.trim()) { return null; }
                    return "--- Sheet: " + name + " ---\n" + csv;
                }).filter(Boolean);
                return Promise.resolve(sheets.join("\n\n"));
            } catch (err) {
                return Promise.reject(new Error("Excel parse error: " + err.message));
            }
        }
    }
};


// ─── Utility Functions ───────────────────────────────────────────────────────

/**
 * Detect whether a text string is likely binary by sampling the first 1 000
 * characters.  A result of true means the ratio of non-printable control
 * characters exceeds 10 %, which is a strong signal for binary content.
 *
 * @param  {string} text — decoded text to inspect
 * @return {boolean}     — true if the text appears to be binary
 */
function looksBinary(text) {
    var sample = text.slice(0, 1000);
    var nonPrintable = 0;
    for (var i = 0; i < sample.length; i++) {
        var code = sample.charCodeAt(i);
        // NUL byte is an immediate binary signal
        if (code === 0) { return true; }
        // Control chars outside common whitespace (TAB LF VT FF CR)
        if (code < 9 || (code > 13 && code < 32)) { nonPrintable++; }
    }
    return nonPrintable / Math.max(1, sample.length) > 0.1;
}

/**
 * Fix garbled filenames caused by UTF-8 bytes being misinterpreted as Latin-1.
 *
 * Browsers send multipart filenames as raw UTF-8 bytes, but HTTP parsers
 * (busboy) may default to Latin-1 decoding.  This turns "快充协议.pdf" into
 * "å¿«å……å¹³å……V1.6.pdf".
 *
 * Strategy: re-encode as latin1 buffer → decode as utf8, then validate the
 * result contains no replacement characters.  If the result is worse, keep
 * the original.
 *
 * @param  {string} name — potentially garbled filename from multer/busboy
 * @return {string}      — corrected filename (or original if already valid)
 */
function fixFilenameEncoding(name) {
    if (!name || !name.length) { return name; }
    try {
        var fixed = Buffer.from(name, "latin1").toString("utf8");
        // Reject if the fix introduced replacement characters (U+FFFD)
        if (fixed.indexOf("�") !== -1) { return name; }
        // Accept if the fix produced CJK / multi-byte characters
        // (the original was likely pure ASCII+garbled bytes)
        var hasMultibyte = false;
        for (var i = 0; i < fixed.length; i++) {
            if (fixed.charCodeAt(i) > 0x7F) { hasMultibyte = true; break; }
        }
        return hasMultibyte ? fixed : name;
    } catch (e) {
        return name;
    }
}

/**
 * Extract the normalised file extension from a filename.
 * Returns the extension in lowercase including the leading dot, e.g. ".pdf".
 *
 * @param  {string} filename — original uploaded filename
 * @return {string}          — normalised extension (e.g. ".docx") or "" if none
 */
function getExtension(filename) {
    return path.extname(filename || "").toLowerCase();
}

/**
 * Look up the parser entry that handles the given file extension.
 *
 * @param  {string} ext — normalised extension (e.g. ".pdf")
 * @return {object|null} — PARSER_REGISTRY entry, or null if unsupported
 */
function findParser(ext) {
    var keys = Object.keys(PARSER_REGISTRY);
    for (var i = 0; i < keys.length; i++) {
        var entry = PARSER_REGISTRY[keys[i]];
        if (entry.extensions.indexOf(ext) !== -1) { return entry; }
    }
    return null;
}


// ─── Main API ────────────────────────────────────────────────────────────────

/**
 * Parse an uploaded file buffer and return plain-text content.
 *
 * Pipeline:
 *   1. Validate file size against MAX_FILE_SIZE.
 *   2. Look up a registered parser by file extension.
 *   3. If found, delegate to the parser's parse() function.
 *   4. If the extension is a known text type, decode as UTF-8.
 *   5. Otherwise, attempt UTF-8 with a binary-detection safety check.
 *
 * @param  {Buffer} buffer           — raw file content from multer
 * @param  {string} originalFilename — original upload filename
 * @return {Promise<{name: string, size: number, content: string}>}
 * @rejects {Error} with .statusCode property for HTTP error mapping
 */
function parseDocument(buffer, originalFilename) {
    var filename = fixFilenameEncoding(originalFilename);
    var ext = getExtension(filename);
    var size = buffer.length;

    // ── Size guard ──
    if (size > MAX_FILE_SIZE) {
        var err = new Error("file too large (max " + Math.round(MAX_FILE_SIZE / 1024 / 1024) + " MB)");
        err.statusCode = 413;
        return Promise.reject(err);
    }

    // ── Registered parser (PDF / Word / Excel) ──
    var parser = findParser(ext);
    if (parser) {
        return parser.parse(buffer).then(function (text) {
            return buildResult(filename, size, text);
        });
    }

    // ── Known text extensions → decode directly ──
    if (TEXT_EXTENSIONS.indexOf(ext) !== -1) {
        return Promise.resolve(
            buildResult(originalFilename, size, buffer.toString("utf8"))
        );
    }

    // ── Fallback: try UTF-8 with binary guard ──
    var text = buffer.toString("utf8");
    if (looksBinary(text)) {
        var binErr = new Error("unsupported file type: " + (ext || "(no extension)"));
        binErr.statusCode = 400;
        return Promise.reject(binErr);
    }
    return Promise.resolve(buildResult(filename, size, text));
}

/**
 * Build a normalised result object and validate that content is non-empty.
 *
 * @param  {string} name    — original filename
 * @param  {number} size    — byte length of the original buffer
 * @param  {string} content — extracted text
 * @return {{name: string, size: number, content: string}}
 * @throws {Error} if content is empty or whitespace-only
 */
function buildResult(name, size, content) {
    if (!content || !content.trim()) {
        var err = new Error("file content is empty");
        err.statusCode = 400;
        throw err;
    }
    return { name: name, size: size, content: content };
}


// ─── Exports ─────────────────────────────────────────────────────────────────

module.exports = {
    MAX_FILE_SIZE: MAX_FILE_SIZE,
    TEXT_EXTENSIONS: TEXT_EXTENSIONS,
    BINARY_EXTENSIONS: BINARY_EXTENSIONS,
    SUPPORTED_EXTENSIONS: SUPPORTED_EXTENSIONS,
    PARSER_REGISTRY: PARSER_REGISTRY,
    parseDocument: parseDocument,
    getExtension: getExtension,
    looksBinary: looksBinary,
    fixFilenameEncoding: fixFilenameEncoding
};
